import requests
from bs4 import BeautifulSoup
import pandas as pd
from io import StringIO
def task_func(url, table_id):
    if not url or not isinstance(url, str):
        raise ValueError("Invalid URL provided.")
    if not table_id or not isinstance(table_id, str):
        raise ValueError("Invalid table_id provided.")

    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.exceptions.HTTPError(f"HTTP request failed: {e}")

    soup = BeautifulSoup(response.text, 'html.parser')
    table = soup.find('table', id=table_id)
    if table is None:
        raise ValueError("Table with the specified ID not found.")

    headers = [th.text.strip() for th in table.find_all('th')] if table.find('th') else None
    data = []
    rows = table.find_all('tr')
    for row in rows:
        cols = row.find_all('td')
        if not cols:
            continue
        cols = [ele.text.strip() for ele in cols]
        data.append(cols)

    if not data:
        return pd.DataFrame()

    return pd.DataFrame(data, columns=headers if headers else None)

