import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    try:
        if webpage_url.startswith("http://") or webpage_url.startswith("https://"):
            response = requests.get(webpage_url)
            response.raise_for_status()
            html_content = response.text
        else:
            with open(webpage_url, 'r', encoding='utf-8') as f:
                html_content = f.read()
    except requests.RequestException as e:
        raise requests.RequestException(f"Failed to fetch the HTML content: {e}")
    except FileNotFoundError as e:
        raise ValueError(f"Local file not found: {e}")

    try:
        tables = pd.read_html(html_content)
        if not tables:
            return 0
        df = tables[0]
        if df.empty:
            return 0
    except ValueError as e:
        return 0
    except Exception as e:
        raise ValueError(f"Error parsing HTML content: {e}")

    try:
        conn = sqlite3.connect(database_name)
        df.to_sql("my_table", conn, if_exists="replace", index=False)
        row_count = len(df)
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")
    finally:
        if conn:
            conn.close()

    return row_count

