        if url.startswith("http"):
            response = requests.get(url, verify=False)
            response.raise_for_status()
            content = response.text
        else:
            with open(url, 'r') as f:
                content = f.read()
    except Exception as e:
        raise ConnectionError(f"Error fetching content: {e}")

